using Bankomaten.Domain;

namespace Bankomaten.Services;

public class UserManagement
{
    /// <summary>
    /// A dictionary containing user data, where the key is a unique identifier (string)
    /// and the value is a User object. This dictionary is initialized with pre-seeded user data
    /// generated by the SeedData.GenerateUsers() method.
    /// </summary>
    public readonly Dictionary<string, User> Users;

    public UserManagement(List<User> users)
    {
        Users = users.ToDictionary(user => user.UserName, StringComparer.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Finds a user by their username from the dictionary of users.
    /// </summary>
    /// <returns>
    /// Returns a User object if a user with the specified username is found;
    /// otherwise, returns null.
    /// </returns>
    public User? FindUser(string username)
    {
        //checks if the username matches any user and returns the user if it does. and if not then null
        return Users.GetValueOrDefault(username);
    }

    /// <summary>Authenticates a user by verifying the provided username and PIN.</summary>
    /// <returns> Returns true if the username and PIN match a user in the stored user data; otherwise, false.</returns>
    public User? Authenticate(string username, string pin)
    {
        var user = FindUser(username);
        return user is not null && user.VerifyPin(pin) ? user : null;
    }
    
    /// <summary>
    /// Adds a transaction entry to the specified user's transaction history.
    /// </summary>
    public void AddUserTransaction(User user, TransactionType transactionType, decimal amount,
        String fromAccountName, String counterpartyName)
    {
        user.TransactionsHistory.Enqueue(
            new Transaction(DateTime.Now, transactionType, amount, fromAccountName, counterpartyName)
        );
    }
}